import unittest
from collections.abc import Sequence
from pylint.graph import get_cycles

class TestGetCycles(unittest.TestCase):
    def test_empty_graph(self):
        """Test with empty graph dictionary."""
        result = get_cycles({})
        self.assertIsInstance(result, Sequence)
        self.assertEqual(len(result), 0)

    def test_single_vertex_no_edges(self):
        """Test graph with single vertex and no edges."""
        graph = {"A": set()}
        result = get_cycles(graph)
        self.assertEqual(len(result), 0)

    def test_two_vertices_no_cycle(self):
        """Test graph with two vertices but no cycle."""
        graph = {"A": {"B"}, "B": set()}
        result = get_cycles(graph)
        self.assertEqual(len(result), 0)

    def test_simple_cycle_two_vertices(self):
        """Test graph with simple 2-vertex cycle."""
        graph = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph)
        self.assertEqual(len(result), 1)
        self.assertEqual(len(result[0]), 2)
        # Cycle could be [A, B] or [B, A]
        cycle = result[0]
        self.assertIn("A", cycle)
        self.assertIn("B", cycle)
        self.assertEqual(set(cycle), {"A", "B"})

    def test_self_loop(self):
        """Test graph with self-loop."""
        graph = {"A": {"A"}}
        result = get_cycles(graph)
        self.assertEqual(len(result), 1)
        self.assertEqual(result[0], ["A"])

    def test_complex_cycle(self):
        """Test graph with more complex cycle."""
        graph = {"A": {"B"}, "B": {"C"}, "C": {"A"}, "D": {"E"}, "E": {"D"}}
        result = get_cycles(graph)
        self.assertEqual(len(result), 2)
        # Check both cycles are present
        cycles_found = set()
        for cycle in result:
            cycles_found.add(frozenset(cycle))
        expected_cycles = {frozenset(["A", "B", "C"]), frozenset(["D", "E"])}
        self.assertEqual(cycles_found, expected_cycles)

    def test_multiple_cycles_same_vertex(self):
        """Test vertex that participates in multiple cycles."""
        graph = {
            "A": {"B"},
            "B": {"A", "C"},
            "C": {"B", "D"},
            "D": {"C"},
        }
        result = get_cycles(graph)
        # There should be 3 cycles: A-B, B-C, C-D
        self.assertEqual(len(result), 3)
        cycles_found = set()
        for cycle in result:
            cycles_found.add(frozenset(cycle))
        expected_cycles = {
            frozenset(["A", "B"]),
            frozenset(["B", "C"]),
            frozenset(["C", "D"])
        }
        self.assertEqual(cycles_found, expected_cycles)

    def test_no_cycle_with_branching(self):
        """Test graph with branching but no cycles."""
        graph = {
            "A": {"B", "C"},
            "B": {"D"},
            "C": {"E"},
            "D": set(),
            "E": set(),
        }
        result = get_cycles(graph)
        self.assertEqual(len(result), 0)

    def test_cycle_with_branching(self):
        """Test graph with branching leading to cycle."""
        graph = {
            "A": {"B", "C"},
            "B": {"D"},
            "C": {"E"},
            "D": {"A"},  # Creates cycle A->B->D->A
            "E": set(),
        }
        result = get_cycles(graph)
        self.assertEqual(len(result), 1)
        cycle = result[0]
        # Cycle should contain A, B, D
        self.assertEqual(set(cycle), {"A", "B", "D"})

    def test_specified_vertices_only(self):
        """Test with specific vertices list."""
        graph = {
            "A": {"B"},
            "B": {"A"},
            "C": {"D"},
            "D": {"C"},
        }
        # Only look for cycles starting from A and B
        result = get_cycles(graph, vertices=["A", "B"])
        self.assertEqual(len(result), 1)
        cycle = result[0]
        self.assertEqual(set(cycle), {"A", "B"})

    def test_specified_vertices_no_cycle(self):
        """Test with vertices that don't form cycles."""
        graph = {
            "A": {"B"},
            "B": {"A"},
            "C": {"D"},
            "D": {"E"},
            "E": set(),
        }
        result = get_cycles(graph, vertices=["C", "D", "E"])
        self.assertEqual(len(result), 0)

    def test_vertices_not_in_graph(self):
        """Test with vertices not present in graph."""
        graph = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph, vertices=["C"])
        self.assertEqual(len(result), 0)

    def test_mixed_vertices_some_in_graph(self):
        """Test with mixed vertices, some in graph, some not."""
        graph = {"A": {"B"}, "B": {"C"}, "C": {"A"}}
        result = get_cycles(graph, vertices=["A", "D", "E"])
        self.assertEqual(len(result), 1)
        self.assertEqual(set(result[0]), {"A", "B", "C"})

    def test_empty_vertices_list(self):
        """Test with empty vertices list."""
        graph = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph, vertices=[])
        self.assertEqual(len(result), 0)

    def test_none_vertices_uses_all(self):
        """Test that None vertices uses all vertices."""
        graph = {"A": {"B"}, "B": {"C"}, "C": {"A"}}
        result = get_cycles(graph, vertices=None)
        self.assertEqual(len(result), 1)
        self.assertEqual(set(result[0]), {"A", "B", "C"})

    def test_disconnected_graph_with_cycles(self):
        """Test disconnected graph with cycles in components."""
        graph = {
            "A": {"B"},
            "B": {"A"},
            "C": set(),
            "D": {"E"},
            "E": {"F"},
            "F": {"D"},
        }
        result = get_cycles(graph)
        self.assertEqual(len(result), 2)
        cycles_found = set()
        for cycle in result:
            cycles_found.add(frozenset(cycle))
        expected_cycles = {frozenset(["A", "B"]), frozenset(["D", "E", "F"])}
        self.assertEqual(cycles_found, expected_cycles)

    def test_large_cycle(self):
        """Test larger cycle."""
        graph = {
            "A": {"B"},
            "B": {"C"},
            "C": {"D"},
            "D": {"E"},
            "E": {"A"},
        }
